#if Clouds == 3 || Clouds == 4
vec3 funClouds3D(in vec3 pos, in vec3 color, const int cloudIT, float dither, bool isReflection) {
    #ifdef TAA
		if(isReflection) dither = fract(dither + fract(frameTimeCounter * 128.0));	//speedup noise for reflections to hide distortions
    #endif 

    #if SHADERLOD_EFFECT_ADAPTER == 1 && !defined DISTANT_HORIZONS && !defined VOXY
    int shaderlodCloudCount = shaderlod_sildur_primary_cloud_count(cloudIT, isReflection,
        max(max(cloud_height - cameraPosition.y, cameraPosition.y - (cloud_height + 200.0)),0.0));
    #else
    int shaderlodCloudCount = cloudIT;
    #endif
    // Retain native absolute dither phase and final edge-mask interval when the count changes.
    float shaderlodCloudDither = shaderlodCloudCount == cloudIT ? dither
        : dither * float(shaderlodCloudCount) / float(cloudIT);
    float maxHeight = cloud_height + 200.0;
    vec3 dV_view = pos.xyz;
    vec3 progress_view = vec3(0.0);
    pos = pos * 2200.0 + cameraPosition; 

    if (cameraPosition.y <= cloud_height) {
        float maxHeight2 = min(maxHeight, pos.y);    
        dV_view *= -(maxHeight2 - cloud_height) / dV_view.y / float(shaderlodCloudCount);
        progress_view = dV_view * shaderlodCloudDither + cameraPosition + dV_view * (maxHeight2 - cameraPosition.y) / dV_view.y;
        if (pos.y < cloud_height) return color;    
    }
    else if (cameraPosition.y < maxHeight) {
        if (dV_view.y <= 0.0) {
            float maxHeight2 = max(cloud_height, pos.y);
            dV_view *= abs(maxHeight2 - cameraPosition.y) / abs(dV_view.y) / float(shaderlodCloudCount);
            progress_view = dV_view * shaderlodCloudDither + cameraPosition + dV_view * float(shaderlodCloudCount);
            dV_view *= -1.0;
        } else {
            float maxHeight2 = min(maxHeight, pos.y);
            dV_view *= -abs(maxHeight2 - cameraPosition.y) / abs(dV_view.y) / float(shaderlodCloudCount);
            progress_view = dV_view * shaderlodCloudDither + cameraPosition - dV_view * float(shaderlodCloudCount);
        }
    }
    else {            
        float maxHeight2 = max(cloud_height, pos.y);    
        dV_view *= -abs(maxHeight2 - maxHeight) / abs(dV_view.y) / float(shaderlodCloudCount);
        progress_view = dV_view * shaderlodCloudDither + cameraPosition + dV_view * (maxHeight2 - cameraPosition.y) / dV_view.y;
        if (pos.y > maxHeight) return color;    
    }

    float mult = length(dV_view) * 0.00390625; 
    vec3 rawColor = color;
    vec3 smoothColor = color;
    float center = (cloud_height + maxHeight) * 0.5;
    float invDifCenter = 1.0 / (maxHeight - center);

    //cache pre computed exponents for density octaves (exp(j*1.05)*0.6) and weights (exp(-j*0.8))
    // j=0: scale=0.6,    weight=1.0
    // j=1: scale=1.7142, weight=0.4493
    // j=2: scale=4.8996, weight=0.2019
    // j=3: scale=13.999, weight=0.0907
    // Total weight = 1.7419
    vec4 stepsScale = vec4(0.6, 1.7142, 4.8996, 13.999);
    vec4 stepsWeight = vec4(1.0, 0.4493, 0.2019, 0.0907);
    vec3 timeVec = vec3(0.5, 0.0, 0.5);

    #if SHADERLOD_EFFECT_ADAPTER == 1 && !defined DISTANT_HORIZONS && !defined VOXY && defined GL_ARB_shader_texture_lod
    bool shaderlodCloudBound = rainStrength == 0.0 && shaderlodPreset == 0 &&
        (isReflection ? shaderlod_optimization_enabled(shaderlodOptReflectionCloudDetail)
                      : shaderlod_optimization_enabled(shaderlodOptCloudPrimaryDetail));
    #endif

    for (int i = 0; i < shaderlodCloudCount; i++) {
        float heightMult = (progress_view.y - center) * invDifCenter;
        vec3 samplePos = progress_view * 0.175 + frameTimeCounter * timeVec;
        float noise = 0.0;

        //cut octaves down for reflections
        int maxOctaves = isReflection ? 2 : 4;

        for (int j = 0; j < maxOctaves; j++) {
            float s = (j == 0) ? stepsScale.x : ((j == 1) ? stepsScale.y : ((j == 2) ? stepsScale.z : stepsScale.w));
            float w = (j == 0) ? stepsWeight.x : ((j == 1) ? stepsWeight.y : ((j == 2) ? stepsWeight.z : stepsWeight.w));

            vec3 pOct = (samplePos * s + frameTimeCounter * float(j) * timeVec * 0.6) * 0.0555555; 
            pOct.xz *= 0.5;

            vec3 p = floor(pOct);
            vec3 f = fract(pOct);
            f = sqrt((f * f) * (3.0 - 2.0 * f));

            vec2 uv = p.xz + f.xz + p.y * 17.0;
            #if SHADERLOD_EFFECT_ADAPTER == 1 && !defined DISTANT_HORIZONS && !defined VOXY && defined GL_ARB_shader_texture_lod
            float xy1;
            float xy2;
            if (shaderlodCloudBound) {
                // Pinned generated noisetex uses nonmipped LINEAR_REPEAT in Iris 1.11.4.
                // LOD0 removes implicit derivatives across both this and later ray iterations.
                xy1 = texture2DLod(noisetex, uv * 0.015625, 0.0).x;
                xy2 = texture2DLod(noisetex, (uv * 0.015625) + 0.265625, 0.0).x;
            } else {
                xy1 = texture2D(noisetex, uv * 0.015625).x;
                xy2 = texture2D(noisetex, (uv * 0.015625) + 0.265625).x;
            }
            #else
            float xy1 = texture2D(noisetex, uv * 0.015625).x; 
            float xy2 = texture2D(noisetex, (uv * 0.015625) + 0.265625).x; 
            #endif
            noise += mix(xy1, xy2, f.y) * w;
            #if SHADERLOD_EFFECT_ADAPTER == 1 && !defined DISTANT_HORIZONS && !defined VOXY && defined GL_ARB_shader_texture_lod
            // Reuse BSL/Unbound positive-remainder native-zero rejection.
            // First weight is 1.0; remaining .4493 + .2019 + .0907 <= .74191.
            // Keep normalization .57408 and the native height/rain expression exact.
            if (shaderlodCloudBound && j == 0 &&
                xy1 >= 0.0 && xy1 <= 1.0 && xy2 >= 0.0 && xy2 <= 1.0 &&
                f.y >= 0.0 && f.y <= 1.0 && noise >= 0.0 && noise <= 1.0 &&
                all(lessThan(abs(uv), vec2(1e6))) &&
                heightMult >= -16.0 && heightMult <= 16.0 && mult >= 0.0 && mult <= 1e6) {
                float shaderlodUpper = ((isReflection ? (noise + 0.44931) * 1.2 : noise + 0.74191) * 0.57408) - 0.56
                    - heightMult * heightMult * 0.3 + rainStrength * 0.2;
                if (shaderlodUpper < -0.001) {
                    // Negative noise forces exact native cloud=0; retain the entire native tail.
                    noise = -1.0;
                    break; // INNER octave loop only; no ray, color, lighting or progress skip.
                }
            }
            #endif

        }

        //normalize noise scale when skipping octaves
        if (isReflection) noise *= 1.2;

        float cloud = (1.0 - pow(0.4, max((noise * 0.57408) - 0.56 - heightMult * heightMult * 0.3 + rainStrength * 0.2, 0.0) * 2.2)) * 20.0; //rain * 0.16
        float heightFactor = clamp((progress_view.y - cloud_height) * 0.005, 0.0, 1.0); 
        float lightsourceVis = pow(heightFactor, 2.3);

        vec3 cloudC = mix(cloudColor2 * 0.05, cloudColor * 0.15, lightsourceVis);
        float blendFactor = 1.0 - exp(-cloud * mult);

        rawColor = mix(rawColor, cloudC, blendFactor);

        float edgeSmoothWeight = blendFactor * (1.0 - (dither - 0.5) * 0.45 * heightFactor);
        smoothColor = mix(smoothColor, cloudC, clamp(edgeSmoothWeight, 0.0, 1.0));

        progress_view += dV_view;
    }

    float upperEdgeMask = clamp((progress_view.y - cloud_height) * 0.005, 0.0, 1.0);
    return mix(rawColor, smoothColor, upperEdgeMask * 0.9);    
}

