	if(depth0 >= 1.0) {
		vec3 cpos = normalize(gbufferModelViewInverse*vec4(fragpos0, 1.0)).xyz;

		#ifndef defskybox
			skyC = pow(max(skyC + (dither * 0.0039215686 - 0.0019607843), 0.0), vec3(1.4));
