	} else {
	#ifdef Shadows
		vec3 finalShadow = funShadows(noise, skyL, translucent, fragpos0, normal);
		vec3 finalLight = (finalShadow*LightC*(SkyL2*skyL)*2.15+ambientC*(1.0/(SkyL2*skyL*0.5+0.5))*1.4)*0.63;
