vec3 funVL(vec3 fragpos){
	//float phase = 2.5+exp(dot(normalize(fragpos), normalize(shadowLightPosition))*3.0)/3.0;
	float VLrays = texture2DLod(colortex3, texcoord, 1).b * 0.175 * VL_amount;
