				 uwWorldPos.xyz += cameraPosition;
			float underwaterDepth = max(0.0, worldpos.y - uwWorldPos.y);

			float causticIntensity = funCaustics(uwWorldPos.xz);
			float shallowFade = utilSmoothstep(0.0, 0.3, underwaterDepth);
