vec4 funReflections(vec3 dir, float noise, float fresnel, vec3 skyC) {
    float steps = 16.0;
    float maxDist = ((vReflData[0].z + dir.z * far * 1.73205) > -near) ? (-near - vReflData[0].z) / dir.z : far * 1.73205;

