        p.x += cos(p0.y + waveX + slowTime) * 0.32;
        p.y += sin(p0.x + waveY - slowTime) * 0.22;

        float layerNetwork = 1.0 - (waveX + waveY) * 0.5;
        causticAccumulator += layerNetwork * scale;

        p *= 1.5;
        scale *= 0.55;
