    // Existing three-phase rotating full-support filter; near/hand/translucent work remains native.
    if (shaderlod_optimization_enabled(shaderlodOptTemporalShadowFilter) && shaderlodPreset == 1 &&
        !shaderlodProtectedHand && !translucent && shadow_samples == 12 && shaderlodShadowCount == 12 &&
        frameCounter >= 0 && frameCounter < 16777216 &&
        shaderlodNear > 0.0 && shaderlodNear < shaderlodFar && shaderlodFar <= 4096.0 &&
        shaderlodTransition >= 0.0 && shaderlodTransition <= shaderlodFar - shaderlodNear &&
        shaderlodTransition * 0.5 <= shaderlodNear &&
        length(fragpos) >= shaderlodFar + 0.5 * shaderlodTransition && length(fragpos) <= 16777216.0) {
        shaderlodTemporalShadow = true;
        shaderlodShadowPhase = int(mod(float(frameCounter),3.0));
    }
    #endif
    #endif
    int shaderlodShadowVisits = shaderlodTemporalShadow ? 4 : shaderlodShadowCount;


	if (diffuse > 0.001) {
	vec3 shadowpos = mat3(gbufferModelViewInverse) * fragpos + gbufferModelViewInverse[3].xyz;
		 shadowpos = mat3(shadowModelView) * shadowpos + shadowModelView[3].xyz;
		 shadowpos = diagonal3(shadowProjection) * shadowpos + shadowProjection[3].xyz;
	float distortion = utilDistortion(shadowpos.xy);
		 shadowpos.xy *= distortion;
	vec2 shading = vec2(1.0);

	if (abs(shadowpos.x) < 1.0-1.5/shadowMapResolution && abs(shadowpos.y) < 1.0-1.5/shadowMapResolution && abs(shadowpos.z) < 6.0){  //only if on shadowmap
		float pdepth = 1.412;	//fallback if PCSS shadows are disabled
		const float threshMul = max(2048.0/shadowMapResolution*shadowDistance*0.0078125,0.95);
		float distortThresh = (sqrt(1.0-diffuse*diffuse)/diffuse+0.7)/distortion;
		shadowpos = shadowpos * vec3(0.5,0.5,0.08333333) + vec3(0.5,0.5,0.5);

		#ifdef PCSS
			pdepth = texture2D(colortex2, texcoord.xy).b;
		#endif

		float rdMul = pdepth*distortion*Nearshadowplane*k/shadowMapResolution;
		float bias = translucent? 0.00014 : distortThresh*0.0001666667*threshMul;

        #if SHADERLOD_EFFECT_ADAPTER == 1 && SHADERLOD_SILDUR_SHADOW_QUERY_GRAPH == 1 && defined IS_IRIS && !defined DISTANT_HORIZONS && !defined VOXY
        vec2 shaderlodQualifiedShading;
        float shaderlodQualifiedFootprint=0.0;
        #ifdef SHADERLOD_SILDUR_RECEIVER_ACTIVE
        if(shaderlodShadowCount==shadow_samples && !shaderlodTemporalShadow) shaderlodQualifiedFootprint=shaderlodSildurReceiverWeight;
        #endif
        bool shaderlodQueryAccepted=false;
        if(!shaderlodProtectedHand && !translucent && shadow_samples==12 &&
            noise>=0.0 && noise<1.0 && shadowMapResolution==3072) {
            if(shaderlodShadowCount==12 && !shaderlodTemporalShadow && shaderlodQualifiedFootprint==0.0)
                shaderlodQueryAccepted=shaderlod_sildur_field_lit(shadowpos,rdMul,bias,shaderlodQualifiedShading);
            if(!shaderlodQueryAccepted) shaderlodQueryAccepted=shaderlod_sildur_raw_query(shadowpos,rdMul,bias,noise,
                shaderlodShadowCount,shaderlodTemporalShadow,shaderlodShadowPhase,shaderlodQualifiedFootprint,shaderlodQualifiedShading);
        }
        if(shaderlodQueryAccepted) shading=shaderlodQualifiedShading;
        else {
        #endif
#ifdef SHADERLOD_SILDUR_RECEIVER_ACTIVE
		if (shaderlodSildurReceiverWeight > 0.0 && shaderlodShadowCount == shadow_samples) {
		vec2 shadows = vec2(0.0);
		float rShadowSamples = 1.0 / float(shaderlodShadowCount);
		for(int shaderlodVisit = 0; shaderlodVisit < shaderlodShadowVisits; shaderlodVisit++){
            int i = shaderlodTemporalShadow ? shaderlodShadowPhase + shaderlodVisit * 3 : shaderlodVisit;
			bool slOmitted = i >= 6 && i < 9;
			if (slOmitted && shaderlodSildurReceiverWeight >= 1.0) continue;
			float slTapWeight = slOmitted ? 1.0 - shaderlodSildurReceiverWeight
			    : (i >= 3 ? 1.0 + 0.5 * shaderlodSildurReceiverWeight : 1.0);
			float alpha = (float(i) + noise) * rShadowSamples;
			float angle = (noise + alpha * 4.0) * 6.2831853;
			vec2 offsetS = vec2(cos(angle), sin(angle)) * sqrt(alpha);

			float weight = 1.0+(i+noise)*rdMul*rShadowSamples*shadowMapResolution;

			shadows.x += shadow2D(shadowtex0,vec3(shadowpos + vec3(rdMul*offsetS,-bias*weight))).x * slTapWeight;
		#ifdef ColoredShadows
			shadows.y += shadow2D(shadowtex1,vec3(shadowpos + vec3(rdMul*offsetS,-bias*weight))).x * slTapWeight;
		#endif
		}
		shading = shadows * (shaderlodTemporalShadow ? 0.25 : rShadowSamples);
		} else {
		vec2 shadows = vec2(0.0);
		float rShadowSamples = 1.0 / float(shaderlodShadowCount);
		for(int shaderlodVisit = 0; shaderlodVisit < shaderlodShadowVisits; shaderlodVisit++){
            int i = shaderlodTemporalShadow ? shaderlodShadowPhase + shaderlodVisit * 3 : shaderlodVisit;
			float alpha = (float(i) + noise) * rShadowSamples;
			float angle = (noise + alpha * 4.0) * 6.2831853;
			vec2 offsetS = vec2(cos(angle), sin(angle)) * sqrt(alpha);

			float weight = 1.0+(i+noise)*rdMul*rShadowSamples*shadowMapResolution;

			shadows.x += shadow2D(shadowtex0,vec3(shadowpos + vec3(rdMul*offsetS,-bias*weight))).x;
		#ifdef ColoredShadows
			shadows.y += shadow2D(shadowtex1,vec3(shadowpos + vec3(rdMul*offsetS,-bias*weight))).x;
		#endif
		}
		shading = shadows * (shaderlodTemporalShadow ? 0.25 : rShadowSamples);
		}
#else
		vec2 shadows = vec2(0.0);
		float rShadowSamples = 1.0 / float(shaderlodShadowCount);
		for(int shaderlodVisit = 0; shaderlodVisit < shaderlodShadowVisits; shaderlodVisit++){
            int i = shaderlodTemporalShadow ? shaderlodShadowPhase + shaderlodVisit * 3 : shaderlodVisit;
			float alpha = (float(i) + noise) * rShadowSamples;
			float angle = (noise + alpha * 4.0) * 6.2831853;
			vec2 offsetS = vec2(cos(angle), sin(angle)) * sqrt(alpha);

			float weight = 1.0+(i+noise)*rdMul*rShadowSamples*shadowMapResolution;

			shadows.x += shadow2D(shadowtex0,vec3(shadowpos + vec3(rdMul*offsetS,-bias*weight))).x;
		#ifdef ColoredShadows
			shadows.y += shadow2D(shadowtex1,vec3(shadowpos + vec3(rdMul*offsetS,-bias*weight))).x;
		#endif
		}
		shading = shadows * (shaderlodTemporalShadow ? 0.25 : rShadowSamples);
#endif
        #if SHADERLOD_EFFECT_ADAPTER == 1 && SHADERLOD_SILDUR_SHADOW_QUERY_GRAPH == 1 && defined IS_IRIS && !defined DISTANT_HORIZONS && !defined VOXY
        }
        #endif
	}
	#if defined raytracedShadows || defined VOXY
		if(shading.x > 0.005)shading.xy *= funRaytraceShadows(shadowLightPosition, fragpos.xyz, noise, float(translucent));
	#endif
	#ifdef ColoredShadows
		finalShading = texture2D(shadowcolor0, shadowpos.xy).rgb*(shading.y-shading.x) + shading.x;
		finalShading *= diffuse;
	#else
		finalShading = vec3(shading.x)*diffuse;
	#endif
		//Prevent light leakage
		finalShading *= mix(skyL,1.0,clamp((eyeBrightnessSmooth.y/255.0-0.125)*4.0,0.0,1.0));
	}
	return finalShading;
}
