vec3 funClouds3D(in vec3 pos, in vec3 color, const int cloudIT, float dither, bool isReflection) {
    // Keep count selection outside the shared kernel. On the pinned primary
    // caller the native count and both budget counts are compile-time constants;
    // no runtime-selected loop ceiling or reciprocal reaches those kernels.
    // Other callers (including reflections) retain the exact existing selection.
    #if SHADERLOD_EFFECT_ADAPTER == 1 && !defined DISTANT_HORIZONS && !defined VOXY
    int shaderlodCloudCount = cloudIT;
    if (isReflection || shaderlod_optimization_enabled(shaderlodOptCloudPrimaryBudget))
        shaderlodCloudCount = shaderlod_sildur_primary_cloud_count(cloudIT, isReflection,
        max(max(cloud_height - cameraPosition.y, cameraPosition.y - (cloud_height + 200.0)),0.0));
    #else
    int shaderlodCloudCount = cloudIT;
    #endif
    #if SHADERLOD_EFFECT_ADAPTER == 1 && !defined DISTANT_HORIZONS && !defined VOXY
    if (!isReflection && cloudIT == cloudsIT) {
        // ceil(N * 7/8) and ceil(N * 3/4), with the existing minimum six.
        // Equality with the admitted helper result is required: these constants
        // do not independently authorize a budget or alter its guards.
        const int balancedCount = ((cloudsIT * 7 + 7) / 8 < 6) ? 6 : (cloudsIT * 7 + 7) / 8;
        const int performanceCount = ((cloudsIT * 3 + 3) / 4 < 6) ? 6 : (cloudsIT * 3 + 3) / 4;
        if (shaderlodCloudCount != cloudIT && shaderlodCloudCount == balancedCount)
            return shaderlod_sildur_cloud_kernel(pos, color, cloudsIT, dither, false, balancedCount);
        if (shaderlodCloudCount != cloudIT && shaderlodCloudCount == performanceCount)
            return shaderlod_sildur_cloud_kernel(pos, color, cloudsIT, dither, false, performanceCount);
        // The pinned helper has no other primary result. Fail native on drift.
        return shaderlod_sildur_cloud_kernel(pos, color, cloudsIT, dither, false, cloudsIT);
    }
    #endif
    return shaderlod_sildur_cloud_kernel(pos, color, cloudIT, dither, isReflection, shaderlodCloudCount);
}
